-- Migration 052 — Descrição de Cargo: Agente de Operações (BSE)
-- Pode rodar mais de uma vez: se o cargo já existir, atualiza; se não existir, cria.
-- Atenção: se já existir "Agente de Operações" da BSE com edições feitas pela tela, elas serão substituídas.

update cargos_desc set
  departamento = $t$Operações$t$, cbo = $t$4211-25$t$,
  missao = $t$Garantir o bom funcionamento da operação diária, executando e apoiando as atividades, acompanhando as rotinas e informando a gerente para que conduza a equipe e tome as decisões necessárias.$t$, sumaria = $t$Apoiar e executar atividades operacionais, acompanhar procedimentos, fiscalizar a organização e o cumprimento das rotinas, prestar suporte à recepção, realizar abertura e fechamento de caixa quando necessário, controlar pendências e elaborar relatório operacional semanal, reportando-se à gerente.$t$,
  resp = $j$[{"titulo": "Organizar e acompanhar a operação", "itens": ["Conferir a organização dos ambientes de atendimento, recepção e áreas de apoio", "Acompanhar a execução das rotinas previstas no cronograma operacional e verificar se foram realizadas nos horários estabelecidos", "Conferir a disponibilidade e a reposição de materiais de uso diário, como toalhas, toalhas descartáveis, shampoos, seringas e demais insumos utilizados na operação", "Verificar as condições de uso e organização de equipamentos e materiais, comunicando necessidades de manutenção ou reposição", "Realizar conferências periódicas e apoiar a contagem de estoque, conforme calendário definido pela empresa"]}, {"titulo": "Executar e dar suporte às atividades operacionais", "itens": ["Executar atividades operacionais necessárias ao funcionamento diário, incluindo preparação, abastecimento e reposição de materiais", "Realizar tarefas específicas, como encher seringas e preparar materiais de selagem, conforme os procedimentos internos e orientações recebidas", "Auxiliar na execução das atividades das recepcionistas sempre que houver necessidade, sem comprometer o acompanhamento geral da operação", "Assumir atividades operacionais de colaboradores ausentes ou apoiar a cobertura de suas rotinas, conforme necessidade e orientação da gerente", "Prestar apoio à auxiliar de limpeza e à balconista sempre que necessário, auxiliando nas atividades operacionais e contribuindo para a continuidade do atendimento e da organização", "Manter postura participativa, colaborativa e proativa, contribuindo para a continuidade e eficiência da operação", "Na ausência da auxiliar de limpeza, tomar a iniciativa de alinhar-se com a equipe e participar da realização da limpeza necessária, contribuindo para manter os ambientes limpos, organizados e adequados ao funcionamento da operação"]}, {"titulo": "Apoiar a recepção e o atendimento", "itens": ["Recepcionar e atender clientes, prestando informações e direcionando-os conforme os procedimentos da empresa", "Apoiar as recepcionistas em períodos de maior movimento ou quando houver apenas uma profissional na recepção", "Auxiliar em atividades de apoio da recepção, como dobrar e organizar toalhas, repor materiais e manter o ambiente organizado", "Verificar necessidades operacionais que possam impactar a experiência do cliente e comunicar situações relevantes à gerente"]}, {"titulo": "Realizar rotinas de caixa", "itens": ["Realizar abertura e fechamento de caixa quando designado para a atividade", "Conferir os valores registrados no sistema e nas máquinas de cartão, bem como os recebimentos em dinheiro, cartão e Pix", "Registrar as informações e movimentações de caixa nos sistemas e controles definidos pela empresa", "Comunicar imediatamente à gerente divergências, inconsistências ou ocorrências identificadas durante a conferência"]}, {"titulo": "Fiscalizar, registrar e elaborar relatórios", "itens": ["Acompanhar o cumprimento dos procedimentos e padrões operacionais estabelecidos pela empresa", "Identificar falhas, atrasos, pendências e oportunidades de melhoria na rotina", "Registrar ocorrências e reunir informações relevantes sobre o funcionamento da operação", "Elaborar e finalizar, ao término de cada semana, o relatório operacional, apresentando à gerente as atividades acompanhadas, pendências, ocorrências e pontos de atenção", "Manter checklists e controles operacionais atualizados e fornecer informações claras e objetivas à gerente"]}, {"titulo": "Comunicar-se e reportar à gerência", "itens": ["Compartilhar informações relevantes sobre a operação e o desempenho das rotinas", "Reportar à gerente falhas, necessidades de correção, ausências, dificuldades da equipe e situações que exijam tomada de decisão", "Manter comunicação clara e respeitosa com recepcionistas, demais departamentos e fornecedores, quando necessário", "Participar de reuniões e alinhamentos relacionados à operação, conforme convocação"]}, {"titulo": "Limites de atuação e relacionamento hierárquico", "itens": ["O Agente de Operações atua no apoio, na execução, no acompanhamento e na fiscalização das atividades", "Não é responsável por delegar tarefas, redistribuir atividades, aplicar medidas disciplinares ou realizar a gestão direta das recepcionistas", "A delegação, as orientações corretivas e as decisões de gestão são responsabilidades da gerente", "Ao identificar uma necessidade ou irregularidade, o Agente deverá comunicar a gerente, que definirá o direcionamento adequado"]}]$j$::jsonb, sucesso = $j$["Executa as rotinas operacionais nos horários estabelecidos", "Mantém ambientes e materiais organizados e abastecidos", "Apoia a recepção, principalmente quando há uma só profissional", "Realiza as rotinas de caixa sem divergências", "Identifica e comunica falhas, atrasos e pendências à gerente", "Entrega o relatório operacional ao final de cada semana", "Respeita os limites de atuação do cargo", "Mantém postura participativa, colaborativa e profissional"]$j$::jsonb,
  resultados = $j$[{"resp": "Operação", "res": "Rotinas do cronograma executadas e acompanhadas nos horários estabelecidos"}, {"resp": "Organização", "res": "Ambientes, equipamentos e materiais organizados e abastecidos"}, {"resp": "Apoio", "res": "Recepção apoiada, sem profissional sozinha em períodos de movimento"}, {"resp": "Caixa", "res": "Abertura e fechamento de caixa conferidos, sem divergências"}, {"resp": "Fiscalização", "res": "Falhas, atrasos e pendências identificados e comunicados à gerente"}, {"resp": "Relatório", "res": "Relatório operacional entregue à gerente ao final de cada semana"}, {"resp": "Comunicação", "res": "Informações claras e objetivas compartilhadas com a gerente e a equipe"}, {"resp": "Postura", "res": "Atuação alinhada aos valores, aos padrões e aos limites do cargo"}]$j$::jsonb, indicadores = $j$[{"nome": "Relatório operacional semanal entregue", "meta": "100%", "freq": "Semanal"}, {"nome": "Rotinas do cronograma cumpridas no horário", "meta": "100%", "freq": "Diário"}, {"nome": "Checklists e controles atualizados", "meta": "100%", "freq": "Diário"}, {"nome": "Divergências de caixa", "meta": "0", "freq": "Diário"}, {"nome": "Ocorrências não comunicadas à gerente", "meta": "0", "freq": "Mensal"}, {"nome": "Boa convivência interna (ocorrências com a equipe)", "meta": "0", "freq": "Mensal"}, {"nome": "Pontualidade", "meta": "100%", "freq": "Diário"}]$j$::jsonb,
  escolaridade = $t$Ensino Médio completo; cursos na área de atendimento, administração ou operações são desejáveis.$t$, experiencia = $t$Desejável experiência mínima de 1 ano em atendimento, recepção ou rotinas operacionais; 2 anos em atividades de atendimento, recepção ou operação serão considerados um diferencial.$t$,
  tecnicos = $j$["Informática", "Pacote Office básico", "Atendimento ao público", "Utilização de sistemas e rotinas de caixa", "Controles operacionais", "Organização de estoque e materiais", "Excel básico/intermediário (desejável)"]$j$::jsonb, comportamentais = $j$["Caráter e ética", "Parceria", "Excelência", "Comprometimento e responsabilidade", "Organização e planejamento", "Comunicação", "Cortesia e cordialidade", "Proatividade", "Atenção aos detalhes", "Senso de urgência", "Trabalho em equipe"]$j$::jsonb,
  updated_at = now()
where cargo = 'Agente de Operações' and empresa = 'BSE';

